import 'package:flutter/material.dart';

/// The Harvestique brand image (a seedling in sunlit soil), round. Generated by frontend/branding/generate_brand_images.py.
class BrandLogo extends StatelessWidget {
  const BrandLogo({super.key, this.size = 96});

  static const asset = 'assets/images/seedling_logo.png';

  final double size;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Image.asset(
        asset,
        width: size,
        height: size,
        filterQuality: FilterQuality.medium,
        semanticLabel: 'Harvestique logo: a young seedling',
      ),
    );
  }
}
